<?php require_once __DIR__.'/../config.php';require_admin();$id=(int)($_GET['id']??0);$m=['title'=>'','slug'=>'','description'=>'','genre'=>'Drama','country'=>'Tanzania','year'=>date('Y'),'poster_url'=>'','backdrop_url'=>'','video_url'=>'','download_url'=>'','featured'=>0,'trending'=>0];if($id){$s=$pdo->prepare('SELECT * FROM movies WHERE id=?');$s->execute([$id]);$m=$s->fetch()?:$m;}if($_SERVER['REQUEST_METHOD']==='POST'){$data=[trim($_POST['title']),trim($_POST['slug']),trim($_POST['description']),trim($_POST['genre']),trim($_POST['country']),(int)$_POST['year'],trim($_POST['poster_url']),trim($_POST['backdrop_url']),trim($_POST['video_url']),trim($_POST['download_url']),isset($_POST['featured'])?1:0,isset($_POST['trending'])?1:0];if($id){$data[]=$id;$s=$pdo->prepare('UPDATE movies SET title=?,slug=?,description=?,genre=?,country=?,year=?,poster_url=?,backdrop_url=?,video_url=?,download_url=?,featured=?,trending=? WHERE id=?');$s->execute($data);}else{$s=$pdo->prepare('INSERT INTO movies(title,slug,description,genre,country,year,poster_url,backdrop_url,video_url,download_url,featured,trending) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute($data);}header('Location: ./');exit;}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Movie editor</title><link rel="stylesheet" href="../assets/movie.css"></head><body class="setup-page"><main class="setup-card"><div class="brand">AFRIKA<span>FLIX</span></div><h1><?=$id?'Edit':'Add'?> movie</h1><form method="post" class="setup-form"><label>Title<input name="title" value="<?=e($m['title'])?>" required></label><label>Slug<input name="slug" value="<?=e($m['slug'])?>" placeholder="movie-title" required></label><label>Description<textarea name="description" rows="5" style="background:#080808;color:#fff;border:1px solid #333;padding:12px"><?=e($m['description'])?></textarea></label><label>Genre<input name="genre" value="<?=e($m['genre'])?>"></label><label>Country<input name="country" value="<?=e($m['country'])?>"></label><label>Year<input type="number" name="year" value="<?=e($m['year'])?>"></label><label>Poster image URL<input name="poster_url" value="<?=e($m['poster_url'])?>"></label><label>Backdrop image URL<input name="backdrop_url" value="<?=e($m['backdrop_url'])?>"></label><label>Streaming video URL<input name="video_url" value="<?=e($m['video_url'])?>" placeholder="https://.../movie.mp4"></label><label>Download URL<input name="download_url" value="<?=e($m['download_url'])?>"></label><label><input type="checkbox" name="featured" <?=$m['featured']?'checked':''?>> Featured</label><label><input type="checkbox" name="trending" <?=$m['trending']?'checked':''?>> Trending</label><button class="btn primary">Save movie</button><a class="btn secondary" href="./">Cancel</a></form></main></body></html>